using System;using System.Collections.Concurrent;using Autodesk.Revit.Attributes;using Autodesk.Revit.DB;using Autodesk.Revit.UI;using SAUDICO.Federate.ACC;using SAUDICO.Federate.Core.Interfaces;using SAUDICO.Federate.Core.Models;using SAUDICO.Federate.Core.Services;using SAUDICO.Federate.Export;using SAUDICO.Federate.Logging;using SAUDICO.Federate.Shared;using SAUDICO.Federate.UI;
namespace SAUDICO.Federate.Revit2025;
public sealed class App:IExternalApplication { internal static Handler Handler=null!;internal static ExternalEvent Event=null!;public Result OnStartup(UIControlledApplication a){LoggingBootstrapper.Start();Handler=new Handler();Event=ExternalEvent.Create(Handler);try{a.CreateRibbonTab(Constants.RibbonTab);}catch(Autodesk.Revit.Exceptions.ArgumentException){}var panels=a.GetRibbonPanels(Constants.RibbonTab);var panel=System.Linq.Enumerable.FirstOrDefault(panels,p=>p.Name==Constants.RibbonPanel)??a.CreateRibbonPanel(Constants.RibbonTab,Constants.RibbonPanel);panel.AddItem(new PushButtonData("SAUDICO.FederationManager",Constants.Command,typeof(App).Assembly.Location,typeof(Command).FullName));return Result.Succeeded;}public Result OnShutdown(UIControlledApplication a){Event.Dispose();LoggingBootstrapper.Stop();return Result.Succeeded;}}
[Transaction(TransactionMode.Manual)]public sealed class Command:IExternalCommand { static FederationManagerWindow? window;public Result Execute(ExternalCommandData d,ref string m,ElementSet e){if(window==null){window=new FederationManagerWindow(App.Handler,App.Event);window.Closed+=(s,x)=>window=null;new System.Windows.Interop.WindowInteropHelper(window).Owner=d.Application.MainWindowHandle;window.Show();}else window.Activate();return Result.Succeeded;}}
public sealed class Handler:IExternalEventHandler,IRevitRequestQueue { readonly ConcurrentQueue<RevitRequest> requests=new();public void Enqueue(RevitRequest r)=>requests.Enqueue(r);public void Execute(UIApplication a){if(!requests.TryDequeue(out var r))return;try{IDocumentOpener opener=r.Job.Model.Type==ModelType.ACC?new CloudDocumentOpener():new FileDocumentOpener();var processor=new JobProcessor(opener,new TemporaryViewBuilder(),new NwcExporter());var result=processor.Process(r.Job,a.Application,new Progress<string>(m=>r.Progress(r.Job,m)),r.Token);r.Complete(result);}catch(Exception ex){r.Fail(ex);}}public string GetName()=>"SAUDICO Federate FIFO queue";}
